mapper.update:
UPDATE sources
SET name = #{name}, title = #{title}, author = #{author,jdbcType=VARCHAR},
    updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT  FROM sources
WHERE user_id = #{userId} AND id IN
#{id}


WHERE src.user_id = #{userId}
AND src.kind = #{kind}

  AND src.search_vector @@ to_tsquery('simple', ari_unaccent(#{prefixQuery}))

GROUP BY src.id

  HAVING (max(s.created_at), src.id) < (#{after.lastSavedAt}, #{after.id})

ORDER BY max(s.created_at) DESC, src.id DESC
LIMIT #{limit}
